-- G4 Part B2 (Addendum 1 of results/PREREG_g4_price_artifacts_2026-10-30.md), written 2026-10-30 BEFORE either list was read. Non-sealed tickers only; read-only. A B2 day is a one-day adjusted move of 30 percent or more that is NOT a Part B candidate (v64 missing, or z below 6).
-- B2a: every such day with a move of 60 percent or more (7 days expected), reviewed in full
WITH ns AS (SELECT s.id AS security_id FROM securities s WHERE s.ticker <> $$SPY$$ AND s.ticker NOT IN (SELECT ticker FROM explore_sealed_tickers)), spy AS (SELECT price_date AS d, adjusted_close / LAG(adjusted_close) OVER (ORDER BY price_date) - 1 AS sr FROM market_prices WHERE security_id = (SELECT id FROM securities WHERE ticker = $$SPY$$)), r AS (SELECT p.security_id, p.price_date AS d, p.adjusted_close / LAG(p.adjusted_close) OVER (PARTITION BY p.security_id ORDER BY p.price_date) - 1 AS ret, p.volume::float8 / NULLIF(AVG(p.volume) OVER (PARTITION BY p.security_id ORDER BY p.price_date ROWS BETWEEN 20 PRECEDING AND 1 PRECEDING), 0) AS vol_ratio FROM market_prices p JOIN ns ON ns.security_id = p.security_id), c AS (SELECT r.security_id, r.d, r.ret, r.vol_ratio, spy.sr, ve.v64 FROM r JOIN spy ON spy.d = r.d LEFT JOIN vol_estimators ve ON ve.security_id = r.security_id AND ve.d = r.d WHERE r.ret IS NOT NULL AND ABS(r.ret) >= 0.30 AND NOT COALESCE(ve.v64 > 0 AND ABS(r.ret - spy.sr) / ve.v64 >= 6, false)), fk AS (SELECT f.security_id, f.effective_date AS d, f.ratio / LAG(f.ratio) OVER (PARTITION BY f.security_id ORDER BY f.effective_date) AS k FROM price_adjustment_factors f) SELECT s.ticker, c.d, ROUND(c.ret::numeric, 3) AS ret, ROUND(c.sr::numeric, 3) AS spy_ret, ROUND(c.v64::numeric, 4) AS v64, ROUND(c.vol_ratio::numeric, 1) AS vol_ratio, cpx.d AS cp_date, ROUND(cpx.k::numeric, 3) AS cp_k, (SELECT COUNT(*) FROM sec_8k_filings f WHERE f.security_id = c.security_id AND f.filing_date BETWEEN c.d - 5 AND c.d + 5) AS n_8k_pm5d, LEFT(ev.title, 70) AS nearest_event FROM c JOIN securities s ON s.id = c.security_id LEFT JOIN LATERAL (SELECT fk.d, fk.k FROM fk WHERE fk.security_id = c.security_id AND fk.k IS NOT NULL AND fk.d BETWEEN c.d - 3 AND c.d + 3 ORDER BY ABS(LN(fk.k)) DESC LIMIT 1) cpx ON true LEFT JOIN LATERAL (SELECT e.title FROM events e JOIN event_entity_relationships rr ON rr.event_id = e.id WHERE rr.entity_id = s.entity_id AND e.event_date BETWEEN c.d - 3 AND c.d + 3 ORDER BY ABS(e.event_date::date - c.d) LIMIT 1) ev ON true WHERE ABS(c.ret) >= 0.60 ORDER BY c.d, s.ticker;
-- B2b: such days with a move of 30 to 60 percent (153 expected): a sample of 40 in the fixed order of md5(ticker and date)
WITH ns AS (SELECT s.id AS security_id FROM securities s WHERE s.ticker <> $$SPY$$ AND s.ticker NOT IN (SELECT ticker FROM explore_sealed_tickers)), spy AS (SELECT price_date AS d, adjusted_close / LAG(adjusted_close) OVER (ORDER BY price_date) - 1 AS sr FROM market_prices WHERE security_id = (SELECT id FROM securities WHERE ticker = $$SPY$$)), r AS (SELECT p.security_id, p.price_date AS d, p.adjusted_close / LAG(p.adjusted_close) OVER (PARTITION BY p.security_id ORDER BY p.price_date) - 1 AS ret, p.volume::float8 / NULLIF(AVG(p.volume) OVER (PARTITION BY p.security_id ORDER BY p.price_date ROWS BETWEEN 20 PRECEDING AND 1 PRECEDING), 0) AS vol_ratio FROM market_prices p JOIN ns ON ns.security_id = p.security_id), c AS (SELECT r.security_id, r.d, r.ret, r.vol_ratio, spy.sr, ve.v64 FROM r JOIN spy ON spy.d = r.d LEFT JOIN vol_estimators ve ON ve.security_id = r.security_id AND ve.d = r.d WHERE r.ret IS NOT NULL AND ABS(r.ret) >= 0.30 AND NOT COALESCE(ve.v64 > 0 AND ABS(r.ret - spy.sr) / ve.v64 >= 6, false)), fk AS (SELECT f.security_id, f.effective_date AS d, f.ratio / LAG(f.ratio) OVER (PARTITION BY f.security_id ORDER BY f.effective_date) AS k FROM price_adjustment_factors f) SELECT s.ticker, c.d, ROUND(c.ret::numeric, 3) AS ret, ROUND(c.sr::numeric, 3) AS spy_ret, ROUND(c.v64::numeric, 4) AS v64, ROUND(c.vol_ratio::numeric, 1) AS vol_ratio, cpx.d AS cp_date, ROUND(cpx.k::numeric, 3) AS cp_k, (SELECT COUNT(*) FROM sec_8k_filings f WHERE f.security_id = c.security_id AND f.filing_date BETWEEN c.d - 5 AND c.d + 5) AS n_8k_pm5d, LEFT(ev.title, 70) AS nearest_event FROM c JOIN securities s ON s.id = c.security_id LEFT JOIN LATERAL (SELECT fk.d, fk.k FROM fk WHERE fk.security_id = c.security_id AND fk.k IS NOT NULL AND fk.d BETWEEN c.d - 3 AND c.d + 3 ORDER BY ABS(LN(fk.k)) DESC LIMIT 1) cpx ON true LEFT JOIN LATERAL (SELECT e.title FROM events e JOIN event_entity_relationships rr ON rr.event_id = e.id WHERE rr.entity_id = s.entity_id AND e.event_date BETWEEN c.d - 3 AND c.d + 3 ORDER BY ABS(e.event_date::date - c.d) LIMIT 1) ev ON true WHERE ABS(c.ret) < 0.60 ORDER BY md5(s.ticker || c.d::text) LIMIT 40;
